async function poll(generation=modeGeneration){if(!gameMode||generation!==modeGeneration)return;try{const next=await api('/api/state');if(generation!==modeGeneration)return;const changed=!S||next.stateRevision!==S.stateRevision;S=next;disconnectToast=false;if(changed){renderUI();draw()}else{const minutes=Number(next.timeOfDayMinutes??360);ui.mapTime.textContent=`${isNight(minutes)?'☾':'☀'} ${formatGameTime(minutes)}`;ui.mapTime.title=`${trafficWindowLabel(trafficWindowAt(minutes))} · ${formatGameTime(minutes)}`;ui.mapTime.dataset.night=String(isNight(minutes));if(S.projects?.length){const cards=ui.projects.querySelectorAll('.project');S.projects.forEach((p,i)=>{const pct=Math.floor(visualProjectProgress(p,minutes)*100),label=cards[i]?.querySelector('.project-top span'),bar=cards[i]?.querySelector('.progress i');if(label)label.textContent=`${pct}%`;if(bar)bar.style.width=`${pct}%`});draw()}if(trafficOverlay){const clock=document.getElementById('trafficClock'),windowLabel=document.getElementById('trafficWindow');if(clock)clock.textContent=`${isNight(minutes)?'☾':'☀'} ${formatGameTime(minutes)}`;if(windowLabel)windowLabel.textContent=trafficWindowLabel(trafficWindowAt(minutes));document.querySelectorAll('.traffic-window').forEach(row=>row.classList.toggle('current',row.dataset.window===trafficWindowAt(minutes)))}}}catch(e){if(generation!==modeGeneration)return;ui.netLabel.textContent='Sala desconectada';if(!disconnectToast){showToast('Se perdió la conexión con la sala. Reintentando…');disconnectToast=true}}setTimeout(()=>poll(generation),500)}
async function startOffline(){const generation=++modeGeneration;window.cvStarting=true;gameMode='offline';offlineAdapter=null;const button=document.getElementById('offlineMode'),error=document.getElementById('modeError');button.disabled=true;error.textContent='Preparando la ciudad…';try{const adapter=await createOfflineWorkerAdapter();if(generation!==modeGeneration)return;offlineAdapter=adapter;offlineAdapter.setRealtimeClock(true);window.cvInfo={ips:[],port:8765};S=await api('/api/state');if(generation!==modeGeneration)return;renderUI();document.getElementById('modeBackdrop').classList.add('hidden');error.textContent='';await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));if(generation!==modeGeneration)return;world.invalidate();draw();showToast('Ciudad offline lista. Se guarda en este navegador.');poll(generation)}catch(e){if(generation!==modeGeneration)return;gameMode=null;offlineAdapter=null;S=null;error.textContent=e.message}finally{if(generation===modeGeneration)button.disabled=false}}
